# ContentStore internals

## src/store.ts (excerpt)

```typescript
const MAX_CHUNK_BYTES = 4096;
const BUSY_RETRIES = 5;
const BUSY_BASE_MS = 25;

export interface Chunk {
  title: string;
  content: string;
  contentType: "code" | "prose";
}

export interface IndexResult {
  chunks: number;
  skipped: boolean;
  source: string;
}

/** Open the database and put it in the shape every other method assumes. */
function openDatabase(path: string): DatabaseInstance {
  const db = new Database(path);
  db.pragma("journal_mode = WAL");
  db.pragma("synchronous = NORMAL");
  db.pragma("busy_timeout = 5000");
  db.pragma("mmap_size = 268435456");
  return db;
}

function createSchema(db: DatabaseInstance): void {
  db.exec(`
    CREATE VIRTUAL TABLE IF NOT EXISTS chunks USING fts5(
      source, title, content, tokenize = 'porter unicode61'
    );
    CREATE VIRTUAL TABLE IF NOT EXISTS chunks_trigram USING fts5(
      source, title, content, tokenize = 'trigram'
    );
    CREATE TABLE IF NOT EXISTS sources (
      label TEXT PRIMARY KEY,
      file_path TEXT,
      content_hash TEXT,
      indexed_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS vocabulary (
      term TEXT PRIMARY KEY,
      df INTEGER NOT NULL
    );
  `);
}

function normalizeSourceLabel(label: string): string {
  return label.trim().replace(/\s+/g, "-").slice(0, 120);
}

function hashContent(content: string): string {
  return createHash("sha256").update(content).digest("hex").slice(0, 32);
}

function splitFrontMatter(text: string): { body: string; title?: string } {
  if (!text.startsWith("---\n")) return { body: text };
  const end = text.indexOf("\n---", 4);
  if (end === -1) return { body: text };
  const head = text.slice(4, end);
  const match = /^title:\s*(.+)$/m.exec(head);
  return { body: text.slice(end + 4), title: match?.[1]?.trim() };
}

function detectContentType(chunk: string): "code" | "prose" {
  const fenced = /^```/m.test(chunk);
  const punctuationHeavy = (chunk.match(/[{}();=<>]/g)?.length ?? 0) / Math.max(1, chunk.length);
  return fenced || punctuationHeavy > 0.02 ? "code" : "prose";
}

function sanitizeQuery(query: string): string {
  return query
    .replace(/["*^]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 0 && !STOPWORDS.has(w.toLowerCase()))
    .map((w) => `"${w}"`)
    .join(" OR ");
}

function bm25Weights(contentType?: "code" | "prose"): [number, number, number] {
  // source, title, content — a title hit is worth roughly three content hits,
  // but only for prose: code chunk titles are often just a file path.
  return contentType === "code" ? [0.5, 2.0, 1.0] : [0.5, 3.0, 1.0];
}

function reciprocalRankFusion(lists: string[][], k = 60): Map<string, number> {
  const scores = new Map<string, number>();
  for (const list of lists) {
    list.forEach((id, i) => {
      scores.set(id, (scores.get(id) ?? 0) + 1 / (k + i + 1));
    });
  }
  return scores;
}

function levenshtein(a: string, b: string, cutoff: number): number {
  if (Math.abs(a.length - b.length) > cutoff) return cutoff + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const row = [i];
    for (let j = 1; j <= b.length; j++) {
      row[j] = Math.min(
        prev[j] + 1,
        row[j - 1] + 1,
        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
    prev = row;
  }
  return prev[b.length];
}

function proximityBonus(content: string, terms: string[]): number {
  const positions = terms.map((t) => content.toLowerCase().indexOf(t.toLowerCase()));
  if (positions.some((p) => p === -1)) return 0;
  const span = Math.max(...positions) - Math.min(...positions);
  return span === 0 ? 0 : 1 / Math.log2(2 + span);
}

/**
 * Run a write against SQLite, retrying the transient lock errors.
 *
 * SQLITE_BUSY and SQLITE_LOCKED mean another connection holds the write lock;
 * both clear on their own. Every other SQLite error is a real fault and is
 * rethrown immediately rather than retried into a five-fold delay.
 */
export function withRetry<T>(fn: () => T, retries = BUSY_RETRIES): T {
  let waited = 0;
  for (let attempt = 0; ; attempt++) {
    try {
      return fn();
    } catch (err) {
      const code = (err as { code?: string }).code ?? "";
      const transient = code === "SQLITE_BUSY" || code === "SQLITE_LOCKED";
      if (!transient || attempt >= retries) throw err;
      waited = BUSY_BASE_MS * 2 ** attempt;
      Atomics.wait(SLEEP_ARRAY, 0, 0, waited);
    }
  }
}

export function pruneVocabulary(db: DatabaseInstance, minDf = 2): number {
  return withRetry(() => db.prepare("DELETE FROM vocabulary WHERE df < ?").run(minDf).changes);
}
```

# Sandbox executor internals

## src/executor.ts (excerpt)

```typescript
const DEFAULT_TIMEOUT_MS = 120_000;
const MAX_OUTPUT_BYTES = 2 * 1024 * 1024;

export type Language =
  | "javascript" | "typescript" | "python" | "shell" | "ruby"
  | "go" | "rust" | "php" | "perl" | "r" | "elixir" | "csharp";

interface RuntimeSpec {
  probe: string[];
  extension: string;
  run: (file: string) => { cmd: string; args: string[] };
}

const RUNTIMES: Record<Language, RuntimeSpec> = {
  javascript: { probe: ["node", "--version"], extension: ".mjs", run: (f) => ({ cmd: "node", args: [f] }) },
  typescript: { probe: ["npx", "tsx", "--version"], extension: ".ts", run: (f) => ({ cmd: "npx", args: ["tsx", f] }) },
  python: { probe: ["python3", "--version"], extension: ".py", run: (f) => ({ cmd: "python3", args: [f] }) },
  shell: { probe: ["bash", "--version"], extension: ".sh", run: (f) => ({ cmd: "bash", args: [f] }) },
  ruby: { probe: ["ruby", "--version"], extension: ".rb", run: (f) => ({ cmd: "ruby", args: [f] }) },
  go: { probe: ["go", "version"], extension: ".go", run: (f) => ({ cmd: "go", args: ["run", f] }) },
  rust: { probe: ["rustc", "--version"], extension: ".rs", run: (f) => ({ cmd: "rust-script", args: [f] }) },
  php: { probe: ["php", "--version"], extension: ".php", run: (f) => ({ cmd: "php", args: [f] }) },
  perl: { probe: ["perl", "--version"], extension: ".pl", run: (f) => ({ cmd: "perl", args: [f] }) },
  r: { probe: ["Rscript", "--version"], extension: ".R", run: (f) => ({ cmd: "Rscript", args: [f] }) },
  elixir: { probe: ["elixir", "--version"], extension: ".exs", run: (f) => ({ cmd: "elixir", args: [f] }) },
  csharp: { probe: ["dotnet", "--version"], extension: ".csx", run: (f) => ({ cmd: "dotnet", args: ["script", f] }) },
};

const runtimeCache = new Map<Language, boolean>();

export function isRuntimeAvailable(language: Language): boolean {
  const cached = runtimeCache.get(language);
  if (cached !== undefined) return cached;
  const spec = RUNTIMES[language];
  try {
    execFileSync(spec.probe[0], spec.probe.slice(1), { stdio: "ignore", timeout: 5000 });
    runtimeCache.set(language, true);
    return true;
  } catch {
    runtimeCache.set(language, false);
    return false;
  }
}

function workDir(): string {
  return mkdtempSync(join(tmpdir(), "ctx-exec-"));
}

function writeProgram(dir: string, language: Language, code: string): string {
  const file = join(dir, `program${RUNTIMES[language].extension}`);
  writeFileSync(file, code, "utf-8");
  return file;
}

function truncateOutput(buf: string): { text: string; truncated: boolean } {
  if (Buffer.byteLength(buf) <= MAX_OUTPUT_BYTES) return { text: buf, truncated: false };
  return { text: buf.slice(0, MAX_OUTPUT_BYTES) + "\n… output truncated", truncated: true };
}

function scrubEnvironment(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const copy = { ...env };
  for (const key of Object.keys(copy)) {
    if (/(TOKEN|SECRET|PASSWORD|API_KEY)$/i.test(key)) delete copy[key];
  }
  copy.NO_COLOR = "1";
  copy.CI = "1";
  return copy;
}

/**
 * Guess the language of a program that arrived without one.
 *
 * The shebang wins when there is one — it is the author's own declaration and
 * is never ambiguous. Only when there is none does the heuristic fall back to
 * looking at syntax, which mistakes a Ruby script for Perl often enough that it
 * is not worth trusting on its own.
 */
export function detectLanguageFromShebang(code: string): Language | null {
  const first = code.split("\n", 1)[0] ?? "";
  if (!first.startsWith("#!")) return null;
  if (/\bnode\b/.test(first)) return "javascript";
  if (/\bpython3?\b/.test(first)) return "python";
  if (/\b(bash|sh|zsh)\b/.test(first)) return "shell";
  if (/\bruby\b/.test(first)) return "ruby";
  if (/\bperl\b/.test(first)) return "perl";
  if (/\bRscript\b/.test(first)) return "r";
  if (/\belixir\b/.test(first)) return "elixir";
  return null;
}

export async function execute(opts: {
  language: Language;
  code: string;
  cwd?: string;
  timeoutMs?: number;
}): Promise<{ stdout: string; stderr: string; exitCode: number; timedOut: boolean }> {
  const dir = workDir();
  try {
    const file = writeProgram(dir, opts.language, opts.code);
    const { cmd, args } = RUNTIMES[opts.language].run(file);
    const child = spawn(cmd, args, {
      cwd: opts.cwd ?? dir,
      env: scrubEnvironment(process.env),
      timeout: opts.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => { stdout += d; });
    child.stderr.on("data", (d) => { stderr += d; });
    const exitCode = await once(child, "close").then(([c]) => c as number);
    return {
      stdout: truncateOutput(stdout).text,
      stderr: truncateOutput(stderr).text,
      exitCode,
      timedOut: child.killed && exitCode === null,
    };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}
```

# Hybrid search internals

## src/search/hybrid.ts (excerpt)

```typescript
const RRF_K = 60;
const INT8_SCALE = 127;

export interface ChunkRow {
  source: string;
  title: string;
  content: string;
  score?: number;
}

export function ensureVectorTable(db: HybridDb): boolean {
  try {
    db.exec(`
      CREATE TABLE IF NOT EXISTS chunk_vectors (
        chunk_rowid INTEGER PRIMARY KEY,
        model TEXT NOT NULL,
        dim INTEGER NOT NULL,
        vec BLOB NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_chunk_vectors_model ON chunk_vectors(model);
    `);
    return true;
  } catch {
    return false;
  }
}

export function encodeVectorInt8(vec: number[]): Buffer {
  const out = Buffer.alloc(vec.length);
  for (let i = 0; i < vec.length; i++) {
    out.writeInt8(Math.max(-128, Math.min(127, Math.round(vec[i] * INT8_SCALE))), i);
  }
  return out;
}

export function decodeVectorInt8(buf: Buffer): number[] {
  const out = new Array<number>(buf.length);
  for (let i = 0; i < buf.length; i++) out[i] = buf.readInt8(i) / INT8_SCALE;
  return out;
}

export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length || a.length === 0) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom === 0 ? 0 : dot / denom;
}

export function fuseRankings<T extends ChunkRow>(
  lexical: T[],
  semantic: T[],
  opts: { limit: number },
): T[] {
  const key = (r: ChunkRow) => `${r.source}\u0000${r.title}\u0000${r.content.slice(0, 64)}`;
  const scores = new Map<string, { row: T; score: number }>();
  const add = (rows: T[]) => rows.forEach((row, i) => {
    const k = key(row);
    const prev = scores.get(k);
    const inc = 1 / (RRF_K + i + 1);
    if (prev) prev.score += inc;
    else scores.set(k, { row, score: inc });
  });
  add(lexical);
  add(semantic);
  return [...scores.values()]
    .sort((a, b) => b.score - a.score)
    .slice(0, opts.limit)
    .map((e) => e.row);
}

export function vectorCoverage(db: HybridDb) {
  if (!ensureVectorTable(db)) return { chunks: 0, vectors: 0, models: [], bytes: 0 };
  const chunks = db.prepare("SELECT count(*) AS n FROM chunks").get().n as number;
  const vectors = db.prepare("SELECT count(*) AS n FROM chunk_vectors").get().n as number;
  const models = db.prepare("SELECT DISTINCT model FROM chunk_vectors").all().map((r) => r.model);
  const bytes = db.prepare("SELECT coalesce(sum(length(vec)), 0) AS n FROM chunk_vectors").get().n as number;
  return { chunks, vectors, models, bytes };
}

export function pruneOrphanVectors(db: HybridDb): number {
  try {
    if (!ensureVectorTable(db)) return 0;
    return db.prepare(
      "DELETE FROM chunk_vectors WHERE chunk_rowid NOT IN (SELECT rowid FROM chunks)",
    ).run().changes;
  } catch {
    return 0;
  }
}

/**
 * Drop every vector that was written by a model other than the current one.
 *
 * Vectors from two embedding models share no geometry: a cosine between a
 * bge-m3 vector and a nomic-embed-text vector is a number with no meaning, and
 * mixing them silently poisons the ranking. Switching models therefore has to
 * invalidate the whole index rather than let it converge on a blend of two.
 */
export function pruneStaleModelVectors(db: HybridDb, currentModel: string): number {
  try {
    if (!ensureVectorTable(db)) return 0;
    return db.prepare("DELETE FROM chunk_vectors WHERE model <> ?").run(currentModel).changes;
  } catch {
    return 0;
  }
}

export function semanticCandidates(
  db: HybridDb,
  queryVec: number[],
  opts: { limit: number; sourceFilter?: string },
): ChunkRow[] {
  if (!ensureVectorTable(db)) return [];
  const rows = db.prepare(`
    SELECT c.source, c.title, c.content, v.vec, v.dim
    FROM chunk_vectors v JOIN chunks c ON c.rowid = v.chunk_rowid
    ${opts.sourceFilter ? "WHERE c.source LIKE ?" : ""}
  `).all(...(opts.sourceFilter ? [`%${opts.sourceFilter}%`] : []));
  return rows
    .map((r) => ({ ...r, score: cosineSimilarity(queryVec, decodeStoredVector(r.vec, r.dim)) }))
    .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
    .slice(0, opts.limit);
}
```
